export declare const SOUND_FORMAT_NAMES: Record<number, string>;
/** Frequency code → Hz lookup (FSB5 sample-header packed encoding). */
export declare const FREQUENCY_VALUES: Record<number, number>;
/** Per-sample metadata chunk types. */
